const FILES = {"src/lib/payments/client.ts":"// One place that talks to Roqqu. Everything else goes through here.\n// Live vs sandbox is decided by environment variables only, so switching is a settings change.\n//   PAYMENTS_MODE=live  -> use Roqqu (otherwise the built-in simulator is used)\n//   ROQQU_ENV=live      -> use the live key header (x-api-key) instead of the test one\nconst BASE = process.env.ROQQU_BASE_URL ?? \"https://service.roqqu.com/v1\";\n\nexport const isLiveMode = () => process.env.PAYMENTS_MODE === \"live\" && Boolean(process.env.ROQQU_SECRET_KEY?.trim());\nexport const isProdKey = () => process.env.ROQQU_ENV === \"live\";\n\nexport class RoqquError extends Error {\n  constructor(message: string, public httpStatus: number | null = null) {\n    super(message);\n  }\n}\n\nfunction authHeaders(): Record<string, string> {\n  const key = process.env.ROQQU_SECRET_KEY?.trim();\n  if (!key) throw new RoqquError(\"ROQQU_SECRET_KEY is not set\");\n  const name = isProdKey() ? \"x-api-key\" : \"x-staging-api-key\";\n  return { [name]: key, Accept: \"application/json\", \"User-Agent\": \"TrustLoop/1.0\" };\n}\n\ntype Opts = { form?: Record<string, string>; json?: unknown; query?: Record<string, string>; timeoutMs?: number };\n\n// Returns the \"data\" part of a successful reply. Throws RoqquError otherwise.\nexport async function roqquRequest(method: \"GET\" | \"POST\", path: string, opts: Opts = {}): Promise<unknown> {\n  const headers = authHeaders();\n  let body: BodyInit | undefined;\n  if (opts.json !== undefined) {\n    headers[\"Content-Type\"] = \"application/json\";\n    body = JSON.stringify(opts.json);\n  } else if (opts.form) {\n    headers[\"Content-Type\"] = \"application/x-www-form-urlencoded\";\n    body = new URLSearchParams(opts.form);\n  }\n  const qs = opts.query ? \"?\" + new URLSearchParams(opts.query).toString() : \"\";\n  let res: Response;\n  try {\n    res = await fetch(`${BASE}${path}${qs}`, {\n      method,\n      headers,\n      body,\n      signal: AbortSignal.timeout(opts.timeoutMs ?? 15000),\n      cache: \"no-store\",\n    });\n  } catch (e) {\n    throw new RoqquError(`Could not reach Roqqu: ${e instanceof Error ? e.message : \"network error\"}`);\n  }\n  const text = await res.text();\n  let parsed: { status?: string; message?: string; data?: unknown };\n  try {\n    parsed = JSON.parse(text);\n  } catch {\n    // For example the Cloudflare \"Just a moment\" page.\n    throw new RoqquError(`Roqqu returned a non-JSON reply (HTTP ${res.status})`, res.status);\n  }\n  if (!res.ok || parsed.status !== \"success\") {\n    throw new RoqquError(`Roqqu error (HTTP ${res.status}): ${parsed.message ?? \"unknown\"}`, res.status);\n  }\n  return parsed.data ?? {};\n}\n\nexport const asRecord = (v: unknown): Record<string, unknown> =>\n  v && typeof v === \"object\" && !Array.isArray(v) ? (v as Record<string, unknown>) : {};\n","src/lib/payments/rates.ts":"import { isLiveMode, roqquRequest, asRecord } from \"./client\";\n\n// The NGN price of one USDT. Live mode asks Roqqu (GET /rates, cached for 5 minutes).\n// If Roqqu is unreachable, or the reply has a shape we do not recognise, we use NGN_PER_USDT.\nexport type Rate = { rate: number; source: \"roqqu\" | \"fixed\" };\n\nconst fixed = (): Rate => ({ rate: Number(process.env.NGN_PER_USDT ?? \"1500\") || 1500, source: \"fixed\" });\nlet cache: { value: Rate; at: number; ttl: number } | null = null;\n\nconst sane = (n: unknown): number | null => {\n  let x = Number(n);\n  if (!Number.isFinite(x) || x <= 0) return null;\n  if (x < 1) x = 1 / x; // some APIs give USD per NGN\n  return x > 100 && x < 20000 ? x : null;\n};\n\n// Roqqu's docs do not show the reply shape, so accept the common ones.\nexport function extractNgn(data: unknown): number | null {\n  const pick = (v: unknown): number | null => {\n    if (typeof v === \"number\" || typeof v === \"string\") return sane(v);\n    const o = asRecord(v);\n    return sane(o.rate ?? o.value ?? o.price ?? o.buy ?? o.sell);\n  };\n  if (Array.isArray(data)) {\n    for (const item of data) {\n      const o = asRecord(item);\n      const code = String(o.currency ?? o.code ?? o.symbol ?? o.name ?? \"\").toLowerCase();\n      if (code === \"ngn\") {\n        const r = pick(o);\n        if (r) return r;\n      }\n    }\n    return null;\n  }\n  const o = asRecord(data);\n  for (const [k, v] of Object.entries(o)) {\n    if (k.toLowerCase() === \"ngn\") {\n      const r = pick(v);\n      if (r) return r;\n    }\n  }\n  for (const key of [\"rates\", \"data\", \"fiat\"]) {\n    if (o[key] !== undefined) {\n      const r = extractNgn(o[key]);\n      if (r) return r;\n    }\n  }\n  return null;\n}\n\nexport async function getNgnPerUsdt(): Promise<Rate> {\n  if (!isLiveMode()) return fixed();\n  if (cache && Date.now() - cache.at < cache.ttl) return cache.value;\n  try {\n    const data = await roqquRequest(\"GET\", \"/rates\", { timeoutMs: 8000 });\n    const r = extractNgn(data);\n    if (r) {\n      cache = { value: { rate: Math.round(r * 100) / 100, source: \"roqqu\" }, at: Date.now(), ttl: 5 * 60_000 };\n      return cache.value;\n    }\n    console.error(\"[roqqu] /rates reply had no usable NGN value\");\n  } catch (e) {\n    console.error(\"[roqqu] /rates failed:\", e instanceof Error ? e.message : e);\n  }\n  cache = { value: fixed(), at: Date.now(), ttl: 60_000 };\n  return cache.value;\n}\n","src/lib/payments/fees.ts":"import { isLiveMode, roqquRequest, asRecord } from \"./client\";\n\n// Roqqu's fee for sending USDT (GET /transaction/fee). Shown to the user before a withdrawal.\nexport type Fee = { percentage: number | null; fee: number | null };\nlet cache: { value: Fee | null; at: number } | null = null;\n\nexport async function getSendFee(): Promise<Fee | null> {\n  if (!isLiveMode()) return null;\n  if (cache && Date.now() - cache.at < 5 * 60_000) return cache.value;\n  let value: Fee | null = null;\n  try {\n    const d = asRecord(await roqquRequest(\"GET\", \"/transaction/fee\", { query: { token: \"usdt\" }, timeoutMs: 8000 }));\n    const pct = Number(d.percentage);\n    const fee = Number(d.fee);\n    value = { percentage: Number.isFinite(pct) ? pct : null, fee: Number.isFinite(fee) ? fee : null };\n  } catch (e) {\n    console.error(\"[roqqu] fee lookup failed:\", e instanceof Error ? e.message : e);\n  }\n  cache = { value, at: Date.now() };\n  return value;\n}\n","src/lib/payments/customers.ts":"import { db } from \"@/lib/db\";\nimport { isLiveMode, roqquRequest, asRecord } from \"./client\";\n\n// Roqqu keeps a record of each customer (the people we generate wallets for).\n// \"verified\" and \"blacklisted\" are flags on that record (GET /customers).\n// Returns null when Roqqu has no such customer, undefined when Roqqu could not be asked.\nexport type CustomerState = { verified: boolean; blacklisted: boolean };\nconst cache = new Map<string, { value: CustomerState | null; at: number }>();\n\nexport async function lookupCustomer(email: string): Promise<CustomerState | null | undefined> {\n  if (!isLiveMode()) return undefined;\n  const key = email.toLowerCase();\n  const hit = cache.get(key);\n  if (hit && Date.now() - hit.at < 10 * 60_000) return hit.value;\n  let value: CustomerState | null = null;\n  try {\n    const data = await roqquRequest(\"GET\", \"/customers\", { timeoutMs: 10000 });\n    const list = Array.isArray(data) ? data : Array.isArray(asRecord(data).customers) ? (asRecord(data).customers as unknown[]) : [];\n    const row = list.map(asRecord).find((c) => String(c.email ?? \"\").toLowerCase() === key);\n    if (row) value = { verified: Number(row.verified) === 1 || row.verified === true, blacklisted: Number(row.blacklisted) === 1 || row.blacklisted === true };\n  } catch (e) {\n    console.error(\"[roqqu] customer lookup failed:\", e instanceof Error ? e.message : e);\n    return undefined; // could not ask Roqqu; do not cache\n  }\n  cache.set(key, { value, at: Date.now() });\n  return value;\n}\n\n// Saves the Roqqu state on the user so the Trust Passport can show a badge without a live call.\nexport async function refreshRoqquStatus(userId: string): Promise<string> {\n  const user = await db.user.findUnique({ where: { id: userId } });\n  if (!user) return \"unknown\";\n  if (!isLiveMode()) return \"sandbox\";\n  const c = await lookupCustomer(user.email);\n  if (c === undefined) return \"unknown\";\n  const status = c === null ? \"not_found\" : c.blacklisted ? \"blacklisted\" : c.verified ? \"verified\" : \"unverified\";\n  await db.user.update({ where: { id: userId }, data: { roqquStatus: status, roqquCheckedAt: new Date() } });\n  return status;\n}\n","src/lib/payments/webhook-crypto.ts":"import { createDecipheriv, createCipheriv } from \"crypto\";\n\n// Roqqu encrypts every webhook body (see \"Decrypt Webhook Body\" in their docs):\n//   algorithm aes-256-ctr, key = first 32 characters of the API key,\n//   IV = the x-api-key header of the webhook request (hex), ciphertext = body.hash (hex).\n// Only someone who holds our API key can produce a body that decrypts to valid JSON,\n// so a successful decrypt is also our proof that the request came from Roqqu.\nexport function decryptWebhook(hashHex: string, apiKey: string, ivHex: string): unknown {\n  const key = Buffer.from(apiKey.slice(0, 32), \"utf8\");\n  if (key.length !== 32) throw new Error(\"API key is shorter than 32 characters\");\n  const iv = Buffer.from(ivHex, \"hex\");\n  if (iv.length !== 16) throw new Error(\"Bad IV\");\n  const d = createDecipheriv(\"aes-256-ctr\", key, iv);\n  const text = Buffer.concat([d.update(Buffer.from(hashHex, \"hex\")), d.final()]).toString(\"utf8\");\n  return JSON.parse(text);\n}\n\n// Used only by the local test script to build a realistic webhook.\nexport function encryptWebhook(payload: unknown, apiKey: string, ivHex: string): string {\n  const key = Buffer.from(apiKey.slice(0, 32), \"utf8\");\n  const c = createCipheriv(\"aes-256-ctr\", key, Buffer.from(ivHex, \"hex\"));\n  return Buffer.concat([c.update(Buffer.from(JSON.stringify(payload), \"utf8\")), c.final()]).toString(\"hex\");\n}\n","src/lib/payments/roqqu.ts":"import type { FundingLink, PaymentProvider, PayoutResult, WalletAddress } from \"./types\";\nimport { mockProvider } from \"./mock\";\nimport { roqquRequest, asRecord } from \"./client\";\nimport { getNgnPerUsdt } from \"./rates\";\n\nconst APP_URL = process.env.APP_URL ?? \"https://trust-loop-theta.vercel.app\";\n\n// Roqqu wants 1 to 20 letters and numbers. Our full reference travels in metadata.\nexport function shortRef(reference: string) {\n  const clean = reference.replace(/[^a-zA-Z0-9]/g, \"\");\n  return clean.slice(-20) || \"TL\" + Date.now().toString(36);\n}\n\n// If Roqqu cannot be reached, fall back to the simulator so the app never breaks.\n// Set PAYMENTS_FALLBACK=off to see the real error instead.\nasync function withFallback<T>(live: () => Promise<T>, fallback: () => Promise<T>): Promise<T> {\n  try {\n    return await live();\n  } catch (e) {\n    console.error(\"[roqqu] falling back to the simulator:\", e);\n    if (process.env.PAYMENTS_FALLBACK === \"off\") throw e;\n    return fallback();\n  }\n}\n\nexport const roqquProvider: PaymentProvider = {\n  createFundingLink(input) {\n    const { reference, amountNgn, taskTitle } = input;\n    return withFallback<FundingLink>(\n      async () => {\n        const [first, ...rest] = (input.customerName ?? \"TrustLoop Hirer\").split(\" \");\n        const data = asRecord(\n          await roqquRequest(\"POST\", \"/payment-links\", {\n            form: {\n              amount: String(amountNgn),\n              amount_currency: \"ngn\",\n              customer_details: JSON.stringify({\n                email: input.customerEmail ?? \"hirer@trustloop.app\",\n                first_name: first || \"TrustLoop\",\n                last_name: rest.join(\" \") || \"Hirer\",\n              }),\n              payment_reference: shortRef(reference),\n              success_url: `${APP_URL}/wallet?added=1`,\n              cancel_url: `${APP_URL}/wallet`,\n              metadata: JSON.stringify({ reference, task: taskTitle.slice(0, 60) }),\n            },\n          }),\n        );\n        const url = String(data.payment_link ?? \"\");\n        if (!url) throw new Error(\"Roqqu did not return a payment link\");\n        const exp = data.expires_at ? new Date(String(data.expires_at)) : null;\n        return { url, reference, expiresAt: exp ?? new Date(Date.now() + 2 * 60 * 60 * 1000) };\n      },\n      () => mockProvider.createFundingLink(input),\n    );\n  },\n\n  sendPayout(input) {\n    const { reference, amountNgn, toAddress } = input;\n    return withFallback<PayoutResult>(\n      async () => {\n        if (!toAddress) throw new Error(\"No destination address for a payout\");\n        const { rate } = await getNgnPerUsdt();\n        const amount = (amountNgn / rate).toFixed(2);\n        const data = asRecord(\n          await roqquRequest(\"POST\", \"/wallets/send\", {\n            form: {\n              amount,\n              network: input.network ?? \"trc20\",\n              to: toAddress,\n              token: (input.token ?? \"usdt\").toLowerCase(),\n            },\n          }),\n        );\n        // Roqqu queues the send and returns its own id. The on-chain hash comes later by webhook.\n        const refid = data.refid ? String(data.refid) : null;\n        return { reference, txHash: null, refid };\n      },\n      () => mockProvider.sendPayout(input),\n    );\n  },\n\n  createWallet(input) {\n    return withFallback<WalletAddress>(\n      async () => {\n        const network = input.network ?? \"trc20\";\n        const data = asRecord(\n          await roqquRequest(\"POST\", \"/wallets/generate-wallet\", {\n            json: {\n              network,\n              customer: JSON.stringify({ email: input.email, first_name: input.firstName, last_name: input.lastName }),\n            },\n          }),\n        );\n        const address = String(data.address ?? \"\");\n        if (!address) throw new Error(\"Roqqu did not return an address\");\n        return { address, network, sandbox: false };\n      },\n      () => mockProvider.createWallet(input),\n    );\n  },\n};\n","src/lib/payments/roqqu-events.ts":"import { Prisma } from \"@prisma/client\";\nimport { db } from \"@/lib/db\";\nimport { notify } from \"@/lib/notify\";\nimport { asRecord, isProdKey } from \"./client\";\nimport { getNgnPerUsdt } from \"./rates\";\n\n// Turns a decrypted Roqqu webhook into changes in our database.\n// Every event is applied once: the event id is stored first, and a repeat is ignored.\nexport type EventResult = \"ok\" | \"duplicate\" | \"ignored\";\n\ntype RoqquEvent = { event_id?: unknown; event_type?: unknown; meta_data?: unknown; datetime?: unknown };\n\nclass Ignored extends Error {}\ntype Tx = Prisma.TransactionClient;\n\nconst naira = (n: number) => \"₦\" + n.toLocaleString(\"en-NG\");\nconst str = (v: unknown) => (v === undefined || v === null ? \"\" : String(v));\nconst num = (v: unknown) => {\n  const n = Number(v);\n  return Number.isFinite(n) ? n : null;\n};\n\nexport async function processRoqquEvent(evt: RoqquEvent): Promise<EventResult> {\n  const eventId = str(evt.event_id);\n  const type = str(evt.event_type);\n  const meta = asRecord(evt.meta_data);\n  if (!eventId || !type) return \"ignored\";\n\n  // Only the USDT-to-naira price needs a network call, so do it before the transaction.\n  const rate = type === \"token_received\" ? (await getNgnPerUsdt()).rate : 0;\n\n  try {\n    await db.$transaction(async (tx) => {\n      await tx.webhookEvent.create({ data: { eventId, type: `roqqu_${type}` } });\n      switch (type) {\n        case \"payment_link_completed\":\n          return paymentLink(tx, meta, false);\n        case \"payment_link_completed_overpaid\":\n          return paymentLink(tx, meta, true);\n        case \"payment_link_failed\":\n          return paymentLinkFailed(tx, meta);\n        case \"token_received\":\n          return tokenReceived(tx, meta, rate);\n        case \"token_sent\":\n          return tokenSent(tx, meta);\n        case \"token_refunded\":\n          return tokenRefunded(tx, meta);\n        default:\n          throw new Ignored(); // not an event we use\n      }\n    });\n    return \"ok\";\n  } catch (e) {\n    if (e instanceof Ignored) return \"ignored\";\n    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === \"P2002\") return \"duplicate\";\n    throw e;\n  }\n}\n\nfunction log(tx: Tx, data: { kind: string; userId?: string | null; reference?: string; hash?: string; token?: string; network?: string; value?: number | null; amountNgn?: number | null; status: string; note?: string }) {\n  return tx.roqquTx.create({\n    data: {\n      kind: data.kind,\n      live: isProdKey(),\n      userId: data.userId ?? null,\n      reference: data.reference || null,\n      hash: data.hash || null,\n      token: data.token ? data.token.toLowerCase() : null,\n      network: data.network ? data.network.toLowerCase() : null,\n      value: data.value ?? null,\n      amountNgn: data.amountNgn ?? null,\n      status: data.status,\n      note: data.note ?? null,\n    },\n  });\n}\n\n// A hirer paid a Roqqu payment link. The payment_reference is the reference we created.\nasync function findDeposit(tx: Tx, meta: Record<string, unknown>) {\n  const refs = [str(meta.payment_reference), str(asRecord(meta.metadata).reference)].filter(Boolean);\n  if (refs.length === 0) throw new Ignored();\n  const dep = await tx.deposit.findFirst({ where: { reference: { in: refs } } });\n  if (!dep) throw new Ignored();\n  return dep;\n}\n\nasync function paymentLink(tx: Tx, meta: Record<string, unknown>, overpaid: boolean) {\n  const dep = await findDeposit(tx, meta);\n  if (dep.status === \"CONFIRMED\") return;\n  const hash = str(meta.hash);\n  const network = str(meta.network).toLowerCase();\n  const token = str(meta.token).toLowerCase();\n  await tx.deposit.update({ where: { id: dep.id }, data: { status: \"CONFIRMED\", txHash: hash || null, network: network || null, token: token || null } });\n  // Same reference the simulator uses, so one payment can never be credited twice.\n  await tx.ledgerEntry.create({\n    data: { userId: dep.userId, type: \"DEPOSIT\", amountNgn: dep.amountNgn, reference: `DEP_${dep.reference}`, note: \"Wallet top-up\" },\n  });\n  await log(tx, {\n    kind: \"PAYMENT_LINK\",\n    userId: dep.userId,\n    reference: dep.reference,\n    hash,\n    token,\n    network,\n    value: num(meta.value),\n    amountNgn: dep.amountNgn,\n    status: overpaid ? \"OVERPAID\" : \"COMPLETED\",\n    note: overpaid ? `Overpaid by ${str(meta.overpaid_amount)} ${token}` : undefined,\n  });\n  await notify(\n    tx,\n    dep.userId,\n    \"Money added\",\n    overpaid\n      ? `${naira(dep.amountNgn)} was added to your wallet. You paid a little extra, so please contact support if you want the difference back.`\n      : `${naira(dep.amountNgn)} was added to your wallet.`,\n    \"/wallet\",\n  );\n}\n\n// The customer paid too little (or the payment failed). Nothing is credited.\nasync function paymentLinkFailed(tx: Tx, meta: Record<string, unknown>) {\n  const dep = await findDeposit(tx, meta);\n  if (dep.status !== \"PENDING\") return;\n  await tx.deposit.update({ where: { id: dep.id }, data: { status: \"FAILED\", txHash: str(meta.hash) || null } });\n  await log(tx, {\n    kind: \"PAYMENT_LINK\",\n    userId: dep.userId,\n    reference: dep.reference,\n    hash: str(meta.hash),\n    token: str(meta.token),\n    network: str(meta.network),\n    value: num(meta.value),\n    amountNgn: dep.amountNgn,\n    status: \"FAILED\",\n    note: `Underpaid by ${str(meta.underpaid_amount)} ${str(meta.token).toLowerCase()}`,\n  });\n  await notify(tx, dep.userId, \"Payment not completed\", \"Your payment did not reach the full amount, so nothing was added. Please try again.\", \"/wallet\");\n}\n\n// USDT arrived at a user's own Roqqu address (not through a payment link).\nasync function tokenReceived(tx: Tx, meta: Record<string, unknown>, rate: number) {\n  const token = str(meta.token).toLowerCase();\n  const status = str(meta.status).toLowerCase();\n  const hash = str(meta.hash);\n  const address = str(meta.address);\n  if (token !== \"usdt\" || !hash || !address || (status && status !== \"confirmed\")) throw new Ignored();\n\n  const row = await tx.depositAddress.findFirst({ where: { address } });\n  const userId = row?.userId ?? (await tx.user.findFirst({ where: { depositAddress: address }, select: { id: true } }))?.id;\n  if (!userId) throw new Ignored();\n\n  const value = num(meta.value);\n  const amountNgn = value && rate ? Math.floor(value * rate) : 0;\n  if (amountNgn < 1) throw new Ignored();\n\n  await tx.ledgerEntry.create({\n    data: { userId, type: \"DEPOSIT\", amountNgn, reference: `CH_${hash}`, note: `USDT received (${str(meta.network).toUpperCase()})` },\n  });\n  await log(tx, { kind: \"CHAIN_DEPOSIT\", userId, reference: address, hash, token, network: str(meta.network), value, amountNgn, status: \"CONFIRMED\" });\n  await notify(tx, userId, \"Money added\", `${value} USDT arrived at your wallet address. ${naira(amountNgn)} was added to your balance.`, \"/wallet\");\n}\n\n// A withdrawal left Roqqu and has an on-chain hash.\nasync function tokenSent(tx: Tx, meta: Record<string, unknown>) {\n  const refid = str(meta.reference);\n  if (!refid) throw new Ignored();\n  const w = await tx.withdrawal.findFirst({ where: { refid } });\n  if (!w) throw new Ignored();\n  const hash = str(meta.hash);\n  if (w.status !== \"COMPLETED\") {\n    await tx.withdrawal.update({ where: { id: w.id }, data: { status: \"COMPLETED\", txHash: hash || w.txHash } });\n    await notify(tx, w.userId, \"Withdrawal sent\", `${naira(w.amountNgn)} was sent as ${w.asset} on ${w.network}.`, \"/wallet\");\n  }\n  await log(tx, { kind: \"SEND\", userId: w.userId, reference: w.reference, hash, token: str(meta.token), network: str(meta.network), value: num(meta.value), amountNgn: w.amountNgn, status: \"SENT\" });\n}\n\n// A send failed and Roqqu refunded it, so the money goes back to the user's wallet.\nasync function tokenRefunded(tx: Tx, meta: Record<string, unknown>) {\n  const refid = str(meta.refid);\n  if (!refid) throw new Ignored();\n  const w = await tx.withdrawal.findFirst({ where: { refid } });\n  if (!w) throw new Ignored();\n  if (w.status === \"FAILED\") return;\n  await tx.withdrawal.update({ where: { id: w.id }, data: { status: \"FAILED\" } });\n  await tx.ledgerEntry.create({\n    data: { userId: w.userId, type: \"REFUND\", amountNgn: w.amountNgn, reference: `${w.reference}_rev`, note: \"Withdrawal refunded\" },\n  });\n  await log(tx, { kind: \"REFUND\", userId: w.userId, reference: w.reference, hash: str(meta.hash), token: str(meta.token), network: str(meta.network), value: num(meta.value), amountNgn: w.amountNgn, status: \"REFUNDED\" });\n  await notify(tx, w.userId, \"Withdrawal returned\", `${naira(w.amountNgn)} was returned to your wallet because the transfer did not go through.`, \"/wallet\");\n}\n","src/lib/payments/types.ts":"export type FundingLink = { url: string; reference: string; expiresAt: Date };\n// refid is Roqqu's id for a queued send. The on-chain hash arrives later by webhook.\nexport type PayoutResult = { reference: string; txHash: string | null; refid?: string | null };\nexport type WalletAddress = { address: string; network: string; sandbox: boolean };\n\nexport interface PaymentProvider {\n  createFundingLink(input: {\n    reference: string;\n    amountNgn: number;\n    taskTitle: string;\n    // Optional. The Roqqu provider needs a customer; defaults are used when missing.\n    customerEmail?: string;\n    customerName?: string;\n  }): Promise<FundingLink>;\n  sendPayout(input: {\n    reference: string;\n    amountNgn: number;\n    // Optional. Needed for a real USDT payout; without it the simulator is used.\n    toAddress?: string;\n    network?: string; // trc20 (default), bep20, ...\n    token?: string; // usdt (default)\n  }): Promise<PayoutResult>;\n  createWallet(input: {\n    email: string;\n    firstName: string;\n    lastName: string;\n    network?: string;\n  }): Promise<WalletAddress>;\n}\n","src/lib/wallet.ts":"import { db } from \"@/lib/db\";\nimport { payments } from \"@/lib/payments\";\n\nexport const NETWORKS = [\"trc20\", \"bep20\"] as const;\nexport type DepositNetwork = (typeof NETWORKS)[number];\n\n// Gives a user a Roqqu deposit address (USDT) on the given network if they do not have one yet.\n// The first network (trc20) is also mirrored on the user row for older code.\nexport async function ensureDepositAddress(userId: string, network: DepositNetwork = \"trc20\") {\n  const user = await db.user.findUnique({ where: { id: userId } });\n  if (!user) return null;\n\n  const have = await db.depositAddress.findUnique({ where: { userId_network: { userId, network } } });\n  if (have) return have;\n\n  // An address made before multi-network support lives on the user row.\n  if (user.depositAddress && (user.depositNetwork ?? \"trc20\").toLowerCase() === network) {\n    return db.depositAddress.upsert({\n      where: { userId_network: { userId, network } },\n      update: {},\n      create: { userId, network, address: user.depositAddress, sandbox: user.depositSandbox },\n    });\n  }\n\n  const [first, ...rest] = user.name.trim().split(/\\s+/);\n  const wallet = await payments.createWallet({\n    email: user.email,\n    firstName: first || \"TrustLoop\",\n    lastName: rest.join(\" \") || \"User\",\n    network,\n  });\n  // The unique (user, network) key means two parallel calls cannot create two addresses.\n  const row = await db.depositAddress.upsert({\n    where: { userId_network: { userId, network } },\n    update: {},\n    create: { userId, network, address: wallet.address, sandbox: wallet.sandbox },\n  });\n  if (network === \"trc20\") {\n    await db.user.updateMany({\n      where: { id: userId, depositAddress: null },\n      data: { depositAddress: row.address, depositNetwork: network, depositSandbox: row.sandbox },\n    });\n  }\n  return row;\n}\n\nexport async function listDepositAddresses(userId: string) {\n  const [rows, user] = await Promise.all([\n    db.depositAddress.findMany({ where: { userId } }),\n    db.user.findUnique({ where: { id: userId } }),\n  ]);\n  const out = rows.map((r) => ({ network: r.network, address: r.address, sandbox: r.sandbox }));\n  if (user?.depositAddress && !out.some((o) => o.network === (user.depositNetwork ?? \"trc20\").toLowerCase())) {\n    out.push({ network: (user.depositNetwork ?? \"trc20\").toLowerCase(), address: user.depositAddress, sandbox: user.depositSandbox });\n  }\n  return out;\n}\n","src/lib/proof.ts":"import type { Prisma } from \"@prisma/client\";\n\n// The Roqqu hash of the hirer's most recent confirmed top-up. Saved on the task's funding record\n// so the payment trail can point to a real transaction.\nexport async function latestRoqquHash(tx: Prisma.TransactionClient, userId: string) {\n  const dep = await tx.deposit.findFirst({\n    where: { userId, status: \"CONFIRMED\", txHash: { not: null } },\n    orderBy: { createdAt: \"desc\" },\n    select: { txHash: true, network: true },\n  });\n  return { txHash: dep?.txHash ?? null, network: dep?.network ?? null };\n}\n\nconst HASH = /^(0x)?[0-9a-fA-F]{64}$/;\nexport function explorerUrl(network: string | null, hash: string | null) {\n  if (!hash || !HASH.test(hash)) return null;\n  switch ((network ?? \"\").toLowerCase()) {\n    case \"trc20\": return `https://tronscan.org/#/transaction/${hash}`;\n    case \"bep20\": return `https://bscscan.com/tx/${hash}`;\n    case \"erc20\": return `https://etherscan.io/tx/${hash}`;\n    case \"bitcoin\": return `https://mempool.space/tx/${hash}`;\n    default: return null;\n  }\n}\n","src/app/actions/withdraw.ts":"\"use server\";\n\nimport { randomBytes } from \"crypto\";\nimport { redirect } from \"next/navigation\";\nimport { db } from \"@/lib/db\";\nimport { getUserId } from \"@/lib/session\";\nimport { getBalance } from \"@/lib/money\";\nimport { notify } from \"@/lib/notify\";\nimport { payments } from \"@/lib/payments\";\nimport { lookupCustomer } from \"@/lib/payments/customers\";\n\nconst ASSETS: Record<string, string[]> = { USDC: [\"BASE\"], USDT: [\"TRC20\", \"BEP20\"] };\n\nexport async function requestWithdrawal(_prev: string | null, formData: FormData) {\n  const userId = await getUserId();\n  if (!userId) redirect(\"/login\");\n\n  const amountNgn = Number(formData.get(\"amountNgn\"));\n  const asset = String(formData.get(\"asset\") ?? \"\");\n  const network = String(formData.get(\"network\") ?? \"\");\n  const address = String(formData.get(\"address\") ?? \"\").trim();\n\n  if (!ASSETS[asset]?.includes(network)) return \"Choose a supported asset and network.\";\n  if (!Number.isInteger(amountNgn) || amountNgn < 100) return \"Enter a whole amount of at least ₦100.\";\n  if (!/^[A-Za-z0-9]{26,64}$/.test(address)) return \"Enter a valid wallet address.\";\n\n  // With live Roqqu, an account Roqqu has blacklisted cannot withdraw.\n  const me = await db.user.findUnique({ where: { id: userId }, select: { email: true } });\n  if (me) {\n    const customer = await lookupCustomer(me.email);\n    if (customer?.blacklisted) return \"Withdrawals are paused for your account. Please contact support.\";\n  }\n\n  const reference = \"TL\" + randomBytes(7).toString(\"hex\");\n  try {\n    await db.$transaction(\n      async (tx) => {\n        const { balance } = await getBalance(tx, userId);\n        if (amountNgn > balance) throw new Error(\"INSUFFICIENT\");\n        await tx.withdrawal.create({ data: { userId, amountNgn, asset, network, address, reference } });\n        await tx.ledgerEntry.create({\n          data: { userId, type: \"WITHDRAWAL\", amountNgn: -amountNgn, reference, note: `${asset} on ${network}` },\n        });\n      },\n      { isolationLevel: \"Serializable\" },\n    );\n  } catch (e) {\n    if (e instanceof Error && e.message === \"INSUFFICIENT\") return \"That is more than your available balance.\";\n    return \"Could not start the withdrawal. Please try again.\";\n  }\n\n  try {\n    const res = await payments.sendPayout({\n      reference,\n      amountNgn,\n      toAddress: address,\n      network: network.toLowerCase(),\n      token: asset.toLowerCase(),\n    });\n    if (res.txHash) {\n      // The simulator finishes at once.\n      await db.withdrawal.update({ where: { reference }, data: { status: \"COMPLETED\", txHash: res.txHash } });\n      await notify(db, userId, \"Withdrawal sent\", `₦${amountNgn.toLocaleString(\"en-NG\")} was sent as ${asset} on ${network}.`, \"/dashboard\");\n    } else if (res.refid) {\n      // Roqqu queued it. The \"token_sent\" webhook (or a status check) completes it.\n      await db.withdrawal.update({ where: { reference }, data: { status: \"PROCESSING\", refid: res.refid } });\n    }\n  } catch {\n    // The transfer failed, so put the money back in the wallet.\n    await db.$transaction([\n      db.withdrawal.update({ where: { reference }, data: { status: \"FAILED\" } }),\n      db.ledgerEntry.create({\n        data: { userId, type: \"REFUND\", amountNgn, reference: `${reference}_rev`, note: \"Withdrawal reversed\" },\n      }),\n    ]);\n    return \"The transfer failed and your balance was not charged. Please try again.\";\n  }\n  redirect(\"/wallet?m=withdrawn\");\n}\n","src/app/actions/roqqu.ts":"\"use server\";\n\nimport { redirect } from \"next/navigation\";\nimport { db } from \"@/lib/db\";\nimport { getUserId } from \"@/lib/session\";\nimport { notify } from \"@/lib/notify\";\nimport { ensureDepositAddress, NETWORKS, type DepositNetwork } from \"@/lib/wallet\";\nimport { isLiveMode, roqquRequest, asRecord } from \"@/lib/payments/client\";\nimport { refreshRoqquStatus } from \"@/lib/payments/customers\";\n\nasync function requireUser() {\n  const userId = await getUserId();\n  if (!userId) redirect(\"/login\");\n  return userId;\n}\n\n// Messages for the wallet page are fixed codes, never text from a URL.\nconst back = (code: string): never => redirect(`/wallet?m=${code}`);\n\nexport async function createAddress(network: string) {\n  const userId = await requireUser();\n  if (!(NETWORKS as readonly string[]).includes(network)) return back(\"badnet\");\n  await ensureDepositAddress(userId, network as DepositNetwork);\n  return back(\"address\");\n}\n\nexport async function checkMyRoqquStatus() {\n  const userId = await requireUser();\n  const status = await refreshRoqquStatus(userId);\n  return back(status === \"sandbox\" ? \"sandbox\" : status === \"unknown\" ? \"unreachable\" : `status_${status}`);\n}\n\n// Asks Roqqu where a withdrawal is (GET /transaction/refId/:refid).\nexport async function checkWithdrawal(reference: string) {\n  const userId = await requireUser();\n  const w = await db.withdrawal.findUnique({ where: { reference } });\n  if (!w || w.userId !== userId) return back(\"nowd\");\n  if (!w.refid || !isLiveMode()) return back(\"nosend\");\n  let data: Record<string, unknown>;\n  try {\n    data = asRecord(await roqquRequest(\"GET\", `/transaction/refId/${encodeURIComponent(w.refid)}`));\n  } catch {\n    return back(\"unreachable\");\n  }\n  const hash = data.tx_hash ? String(data.tx_hash) : \"\";\n  if (!hash) return back(\"pending\");\n  if (w.status !== \"COMPLETED\") {\n    await db.withdrawal.update({ where: { id: w.id }, data: { status: \"COMPLETED\", txHash: hash } });\n    await notify(db, userId, \"Withdrawal sent\", `₦${w.amountNgn.toLocaleString(\"en-NG\")} was sent as ${w.asset} on ${w.network}.`, \"/wallet\");\n  }\n  return back(\"confirmed\");\n}\n\n// Asks Roqqu to refund a send that never went through (POST /transaction/refund).\n// Roqqu only allows this an hour after the send, and only if it failed on-chain.\n// The money comes back to the wallet when Roqqu's \"token_refunded\" webhook arrives.\nexport async function recoverWithdrawal(reference: string) {\n  const userId = await requireUser();\n  const w = await db.withdrawal.findUnique({ where: { reference } });\n  if (!w || w.userId !== userId || !w.refid || !isLiveMode()) return back(\"nosend\");\n  if (w.status !== \"PROCESSING\" || w.txHash) return back(\"notstuck\");\n  if (Date.now() - w.createdAt.getTime() < 60 * 60 * 1000) return back(\"toosoon\");\n  try {\n    await roqquRequest(\"POST\", \"/transaction/refund\", { form: { refid: w.refid } });\n  } catch {\n    return back(\"refund_denied\");\n  }\n  await db.withdrawal.update({ where: { id: w.id }, data: { status: \"REFUND_REQUESTED\" } });\n  return back(\"refund_ok\");\n}\n","src/app/api/roqqu/webhook/route.ts":"import { decryptWebhook } from \"@/lib/payments/webhook-crypto\";\nimport { processRoqquEvent } from \"@/lib/payments/roqqu-events\";\n\n// Roqqu calls this address when money arrives or leaves.\n// Set it as your webhook URL in the Roqqu dashboard:  https://<your-site>/api/roqqu/webhook\nexport async function POST(req: Request) {\n  const keys = [process.env.ROQQU_WEBHOOK_KEY, process.env.ROQQU_SECRET_KEY].map((k) => k?.trim()).filter((k): k is string => Boolean(k));\n  if (keys.length === 0) return Response.json({ error: \"not configured\" }, { status: 503 });\n\n  let body: { hash?: unknown };\n  try {\n    body = await req.json();\n  } catch {\n    return Response.json({ error: \"bad body\" }, { status: 400 });\n  }\n  const iv = req.headers.get(\"x-api-key\") ?? \"\";\n  if (typeof body.hash !== \"string\" || !iv) return Response.json({ error: \"bad request\" }, { status: 400 });\n\n  // A body that does not decrypt with our key did not come from Roqqu. Plain-text bodies are never accepted.\n  let payload: unknown = null;\n  for (const key of keys) {\n    try {\n      payload = decryptWebhook(body.hash, key, iv);\n      break;\n    } catch {\n      /* try the next key */\n    }\n  }\n  if (!payload || typeof payload !== \"object\") return Response.json({ error: \"cannot verify\" }, { status: 401 });\n\n  try {\n    const result = await processRoqquEvent(payload as Record<string, unknown>);\n    return Response.json({ received: true, result });\n  } catch (e) {\n    console.error(\"[roqqu webhook] failed:\", e);\n    return Response.json({ error: \"failed\" }, { status: 500 }); // Roqqu can retry this event\n  }\n}\n","src/app/admin/roqqu/page.tsx":"import { Suspense } from \"react\";\nimport { notFound } from \"next/navigation\";\nimport { Activity, Wallet, ArrowDownLeft, ArrowUpRight, RotateCcw, Radio } from \"lucide-react\";\nimport { db } from \"@/lib/db\";\nimport { getUserId } from \"@/lib/session\";\nimport { isLiveMode, isProdKey, roqquRequest, asRecord } from \"@/lib/payments/client\";\nimport { getNgnPerUsdt } from \"@/lib/payments/rates\";\n\nconst naira = (n: number) => \"₦\" + n.toLocaleString(\"en-NG\");\n\nexport default function RoqquAdminPage() {\n  return (\n    <Suspense fallback={<div className=\"p-10 text-sm text-muted\">Loading...</div>}>\n      <Inner />\n    </Suspense>\n  );\n}\n\n// Only the emails in ADMIN_EMAILS (comma separated) can open this page.\nasync function Inner() {\n  const userId = await getUserId();\n  const admins = (process.env.ADMIN_EMAILS ?? \"\").split(\",\").map((e) => e.trim().toLowerCase()).filter(Boolean);\n  const me = userId ? await db.user.findUnique({ where: { id: userId }, select: { email: true } }) : null;\n  if (!me || !admins.includes(me.email.toLowerCase())) notFound();\n\n  const [addrRows, legacyOnly, deps, ledger, wds, byKind, lastEvent, recent, rate] = await Promise.all([\n    db.depositAddress.groupBy({ by: [\"sandbox\"], _count: true }),\n    db.user.count({ where: { depositAddress: { not: null }, addresses: { none: {} } } }),\n    db.deposit.groupBy({ by: [\"status\"], _count: true, _sum: { amountNgn: true } }),\n    db.ledgerEntry.groupBy({ by: [\"type\"], _count: true, _sum: { amountNgn: true } }),\n    db.withdrawal.groupBy({ by: [\"status\"], _count: true, _sum: { amountNgn: true } }),\n    db.roqquTx.groupBy({ by: [\"kind\", \"live\"], _count: true, _sum: { amountNgn: true } }),\n    db.webhookEvent.findFirst({ where: { type: { startsWith: \"roqqu_\" } }, orderBy: { processedAt: \"desc\" } }),\n    db.roqquTx.findMany({ orderBy: { createdAt: \"desc\" }, take: 12 }),\n    getNgnPerUsdt(),\n  ]);\n\n  // Roqqu's own numbers for our account, only when live.\n  let stats: Record<string, unknown> | null = null;\n  if (isLiveMode()) {\n    try {\n      stats = asRecord(await roqquRequest(\"GET\", \"/analytics/stats\", { timeoutMs: 8000 }));\n    } catch {\n      stats = null;\n    }\n  }\n\n  const real = addrRows.filter((r) => !r.sandbox).reduce((a, r) => a + r._count, 0);\n  const sim = addrRows.filter((r) => r.sandbox).reduce((a, r) => a + r._count, 0) + legacyOnly;\n  const dep = (s: string) => deps.find((d) => d.status === s);\n  const led = (t: string) => ledger.find((l) => l.type === t);\n  const wd = (s: string) => wds.find((w) => w.status === s);\n  const kind = (k: string, live: boolean) => byKind.find((b) => b.kind === k && b.live === live);\n  const mode = isLiveMode() ? (isProdKey() ? \"Live\" : \"Roqqu test environment\") : \"Simulator\";\n\n  const tiles: [string, string, string, typeof Wallet][] = [\n    [\"Wallet addresses made\", String(real + sim), `${real} on Roqqu, ${sim} simulated`, Wallet],\n    [\"Top-ups confirmed\", String(dep(\"CONFIRMED\")?._count ?? 0), naira(dep(\"CONFIRMED\")?._sum.amountNgn ?? 0), ArrowDownLeft],\n    [\"Paid to freelancers\", String(led(\"TASK_PAYOUT\")?._count ?? 0), naira(led(\"TASK_PAYOUT\")?._sum.amountNgn ?? 0), Activity],\n    [\"Withdrawals sent\", String(wd(\"COMPLETED\")?._count ?? 0), naira(wd(\"COMPLETED\")?._sum.amountNgn ?? 0), ArrowUpRight],\n    [\"Withdrawals in progress\", String((wd(\"PROCESSING\")?._count ?? 0) + (wd(\"REFUND_REQUESTED\")?._count ?? 0)), \"Waiting on Roqqu\", Radio],\n    [\"Returned to wallets\", String((wd(\"FAILED\")?._count ?? 0)), naira(wd(\"FAILED\")?._sum.amountNgn ?? 0), RotateCcw],\n  ];\n\n  return (\n    <main className=\"mx-auto max-w-4xl space-y-5 px-5 py-6\">\n      <header>\n        <h1 className=\"text-2xl font-extrabold\">Roqqu activity</h1>\n        <p className=\"mt-1 text-sm text-muted\">\n          Counts come from TrustLoop's own records of every Roqqu call and webhook. Mode: <b>{mode}</b>. Price of 1 USDT: <b>{naira(Math.round(rate.rate))}</b> ({rate.source === \"roqqu\" ? \"live from Roqqu\" : \"fixed\"}).\n        </p>\n        <p className=\"mt-1 text-sm text-muted\">\n          Last Roqqu webhook received: <b>{lastEvent ? lastEvent.processedAt.toLocaleString(\"en-NG\") : \"none yet\"}</b>\n        </p>\n      </header>\n\n      <div className=\"grid grid-cols-2 gap-3 sm:grid-cols-3\">\n        {tiles.map(([label, big, small, Icon]) => (\n          <div key={label} className=\"rounded-2xl border border-ink/10 bg-white p-4 shadow-sm shadow-ink/5\">\n            <Icon className=\"h-5 w-5 text-forest\" aria-hidden />\n            <p className=\"mt-2 text-2xl font-extrabold\">{big}</p>\n            <p className=\"text-sm font-semibold\">{label}</p>\n            <p className=\"text-xs text-muted\">{small}</p>\n          </div>\n        ))}\n      </div>\n\n      <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"text-lg font-bold\">Confirmed by Roqqu webhooks</h2>\n        <table className=\"mt-3 w-full text-left text-sm\">\n          <thead className=\"text-xs uppercase text-muted\"><tr><th className=\"py-1\">Event</th><th>Live</th><th>Test or simulated</th></tr></thead>\n          <tbody className=\"divide-y divide-ink/10\">\n            {[\n              [\"PAYMENT_LINK\", \"Payment links paid\"],\n              [\"CHAIN_DEPOSIT\", \"USDT sent to user addresses\"],\n              [\"SEND\", \"Withdrawals sent on-chain\"],\n              [\"REFUND\", \"Failed sends refunded\"],\n            ].map(([k, label]) => (\n              <tr key={k}>\n                <td className=\"py-2 font-semibold\">{label}</td>\n                <td>{kind(k, true)?._count ?? 0}</td>\n                <td>{kind(k, false)?._count ?? 0}</td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      </section>\n\n      {stats && (\n        <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n          <h2 className=\"text-lg font-bold\">Roqqu's own numbers for TrustLoop</h2>\n          <dl className=\"mt-3 grid grid-cols-3 gap-3 text-sm\">\n            {([\"total_volume\", \"total_credit\", \"total_debit\"] as const).map((k) => (\n              <div key={k}>\n                <dt className=\"text-muted\">{k.replace(\"total_\", \"Total \")}</dt>\n                <dd className=\"text-xl font-extrabold\">{String(stats?.[k] ?? \"-\")}</dd>\n              </div>\n            ))}\n          </dl>\n        </section>\n      )}\n\n      <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"text-lg font-bold\">Latest events</h2>\n        {recent.length === 0 ? (\n          <p className=\"mt-2 text-sm text-muted\">No Roqqu events yet.</p>\n        ) : (\n          <ul className=\"mt-3 divide-y divide-ink/10 text-sm\">\n            {recent.map((r) => (\n              <li key={r.id} className=\"flex flex-wrap items-center justify-between gap-2 py-2\">\n                <span><b>{r.kind.replace(\"_\", \" \").toLowerCase()}</b> · {r.status.toLowerCase()}{r.network ? ` · ${r.network}` : \"\"}</span>\n                <span className=\"text-xs text-muted\">{r.live ? \"live\" : \"test\"} · {r.createdAt.toLocaleString(\"en-NG\")}</span>\n              </li>\n            ))}\n          </ul>\n        )}\n      </section>\n    </main>\n  );\n}\n","src/app/wallet/page.tsx":"import { Suspense } from \"react\";\nimport Link from \"next/link\";\nimport { redirect } from \"next/navigation\";\nimport { ArrowLeft, ArrowDownLeft, ArrowUpRight, Lock, Wallet, ShieldCheck, ExternalLink, RefreshCw, Gauge } from \"lucide-react\";\nimport { db } from \"@/lib/db\";\nimport { getUserId } from \"@/lib/session\";\nimport { getBalance } from \"@/lib/money\";\nimport AddMoneyForm from \"@/components/AddMoneyForm\";\nimport CopyButton from \"@/components/CopyButton\";\nimport { createAddress, checkMyRoqquStatus, checkWithdrawal, recoverWithdrawal } from \"@/app/actions/roqqu\";\nimport { listDepositAddresses, NETWORKS } from \"@/lib/wallet\";\nimport { getNgnPerUsdt } from \"@/lib/payments/rates\";\nimport { getSendFee } from \"@/lib/payments/fees\";\nimport { isLiveMode } from \"@/lib/payments/client\";\nimport { explorerUrl } from \"@/lib/proof\";\n\nconst naira = (n: number) => \"₦\" + n.toLocaleString(\"en-NG\");\nconst LABEL: Record<string, string> = {\n  DEPOSIT: \"Money added\",\n  TASK_FUND: \"Locked for a task\",\n  TASK_PAYOUT: \"Task payment received\",\n  WITHDRAWAL: \"Withdrawal\",\n  REFUND: \"Withdrawal returned\",\n};\nconst W_STATUS: Record<string, [string, string]> = {\n  PENDING: [\"Starting\", \"bg-cream text-muted\"],\n  PROCESSING: [\"Sending\", \"bg-amber-50 text-amber-800\"],\n  COMPLETED: [\"Sent\", \"bg-emerald-100 text-emerald-800\"],\n  FAILED: [\"Returned to wallet\", \"bg-cream text-muted\"],\n  REFUND_REQUESTED: [\"Refund requested\", \"bg-amber-50 text-amber-800\"],\n};\nconst MESSAGES: Record<string, [boolean, string]> = {\n  withdrawn: [true, \"Withdrawal started. You will be notified when it is sent.\"],\n  address: [true, \"Your address is ready.\"],\n  badnet: [false, \"That network is not supported.\"],\n  sandbox: [true, \"Sandbox mode: there is no Roqqu account to check yet.\"],\n  unreachable: [false, \"Could not reach Roqqu just now. Please try again in a moment.\"],\n  status_verified: [true, \"Your Roqqu account is verified. A badge now shows on your Trust Passport.\"],\n  status_unverified: [true, \"Your Roqqu account exists but is not verified yet.\"],\n  status_not_found: [false, \"Roqqu has no account for this email yet.\"],\n  status_blacklisted: [false, \"Roqqu has blocked this account. Please contact support.\"],\n  nosend: [false, \"This withdrawal cannot be checked.\"],\n  nowd: [false, \"Withdrawal not found.\"],\n  pending: [true, \"Roqqu has not put this transfer on the blockchain yet. Check again shortly.\"],\n  confirmed: [true, \"Confirmed. The transfer is on the blockchain.\"],\n  notstuck: [false, \"This withdrawal is not stuck.\"],\n  toosoon: [false, \"Roqqu only allows a refund an hour after the transfer was started.\"],\n  refund_denied: [false, \"Roqqu did not accept the refund yet. It only refunds transfers that failed on the blockchain.\"],\n  refund_ok: [true, \"Refund requested. Your balance will be restored when Roqqu confirms it.\"],\n};\n\ntype Search = Promise<{ need?: string; task?: string; added?: string; m?: string }>;\n\nexport default function WalletPage({ searchParams }: { searchParams: Search }) {\n  return (\n    <Suspense fallback={<div className=\"p-10 text-sm text-muted\">Loading your wallet...</div>}>\n      <WalletInner searchParams={searchParams} />\n    </Suspense>\n  );\n}\n\nasync function WalletInner({ searchParams }: { searchParams: Search }) {\n  const sp = await searchParams;\n  const userId = await getUserId();\n  if (!userId) redirect(\"/login\");\n  const user = await db.user.findUnique({ where: { id: userId } });\n  if (!user) redirect(\"/login\");\n\n  const [bal, entries, addresses, withdrawals, rate, fee] = await Promise.all([\n    getBalance(db, userId),\n    db.ledgerEntry.findMany({ where: { userId }, orderBy: { createdAt: \"desc\" }, take: 15 }),\n    listDepositAddresses(userId),\n    db.withdrawal.findMany({ where: { userId }, orderBy: { createdAt: \"desc\" }, take: 6 }),\n    getNgnPerUsdt(),\n    getSendFee(),\n  ]);\n  const sandbox = process.env.ROQQU_ENV !== \"live\";\n  const live = isLiveMode();\n  const need = Math.max(100, Number(sp.need) || 0);\n  const note = sp.m ? MESSAGES[sp.m] : undefined;\n  const statusText: Record<string, string> = {\n    verified: \"Verified on Roqqu\",\n    unverified: \"On Roqqu, not verified yet\",\n    not_found: \"Not found on Roqqu\",\n    blacklisted: \"Blocked by Roqqu\",\n  };\n\n  return (\n    <main className=\"mx-auto max-w-3xl space-y-5 px-5 py-6\">\n      <Link href=\"/dashboard\" className=\"inline-flex items-center gap-1 text-sm font-semibold text-muted hover:text-ink\">\n        <ArrowLeft className=\"h-4 w-4\" aria-hidden /> Dashboard\n      </Link>\n\n      {sp.added && (\n        <p role=\"status\" className=\"rounded-xl bg-emerald-100 px-4 py-3 text-sm font-semibold text-emerald-800\">\n          Payment received. Your wallet will update as soon as Roqqu confirms it.\n        </p>\n      )}\n      {note && (\n        <p role=\"status\" className={`rounded-xl px-4 py-3 text-sm font-semibold ${note[0] ? \"bg-emerald-100 text-emerald-800\" : \"bg-amber-50 text-amber-800\"}`}>\n          {note[1]}\n        </p>\n      )}\n      {sp.need && (\n        <p role=\"status\" className=\"rounded-xl bg-amber-50 px-4 py-3 text-sm font-semibold text-amber-800\">\n          Your wallet is {naira(Number(sp.need) || 0)} short for that task. Add money, then fund the task again.\n        </p>\n      )}\n\n      <section className=\"rounded-3xl bg-forest p-6 text-white\">\n        <p className=\"flex items-center gap-2 text-sm font-semibold text-white/80\">\n          <Wallet className=\"h-4 w-4\" aria-hidden /> Wallet balance\n        </p>\n        <p className=\"mt-2 text-4xl font-extrabold\">{naira(bal.balance)}</p>\n        <div className=\"mt-5 grid grid-cols-3 gap-3 text-sm\">\n          <div><p className=\"text-white/70\">Added</p><p className=\"font-bold\">{naira(bal.deposited)}</p></div>\n          <div><p className=\"text-white/70\">Earned</p><p className=\"font-bold\">{naira(bal.earned)}</p></div>\n          <div><p className=\"text-white/70\">Locked in tasks</p><p className=\"font-bold\">{naira(bal.funded)}</p></div>\n        </div>\n      </section>\n\n      <div className=\"grid gap-5 md:grid-cols-2\">\n        <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n          <h2 className=\"text-lg font-bold\">Add money</h2>\n          <p className=\"mt-1 text-sm text-muted\">\n            Top up your wallet, then fund tasks from it.{\" \"}\n            {sandbox ? \"Sandbox: a simulator stands in for the Roqqu payment page.\" : \"You pay on Roqqu's secure payment page and can choose Bitcoin or USDT.\"}\n          </p>\n          <div className=\"mt-4\">\n            <AddMoneyForm defaultAmount={need} sandbox={sandbox} />\n          </div>\n        </section>\n\n        <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n          <h2 className=\"text-lg font-bold\">Your Roqqu wallet addresses</h2>\n          <p className=\"mt-1 text-sm text-muted\">\n            Send USDT to one of these from any wallet and your balance goes up by itself.\n          </p>\n          <div className=\"mt-3 space-y-3\">\n            {NETWORKS.map((n) => {\n              const a = addresses.find((x) => x.network === n);\n              return (\n                <div key={n}>\n                  <p className=\"text-xs font-bold uppercase tracking-wide text-muted\">USDT on {n.toUpperCase()}</p>\n                  {a ? (\n                    <>\n                      <p className=\"mt-1 break-all rounded-xl bg-cream px-3 py-2 font-mono text-xs\">{a.address}</p>\n                      <div className=\"mt-2 flex flex-wrap items-center gap-3\">\n                        <CopyButton text={a.address} />\n                        {a.sandbox && <span className=\"text-xs text-muted\">Simulated sandbox address. It exists on no real network.</span>}\n                      </div>\n                    </>\n                  ) : (\n                    <form action={createAddress.bind(null, n)} className=\"mt-1\">\n                      <button className=\"rounded-xl border border-ink/15 px-4 py-2 text-sm font-semibold hover:bg-cream\">Create {n.toUpperCase()} address</button>\n                    </form>\n                  )}\n                </div>\n              );\n            })}\n          </div>\n        </section>\n      </div>\n\n      <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"flex items-center gap-2 text-lg font-bold\"><Gauge className=\"h-5 w-5 text-forest\" aria-hidden /> Rate, fees and your Roqqu account</h2>\n        <dl className=\"mt-3 grid gap-3 text-sm sm:grid-cols-3\">\n          <div>\n            <dt className=\"text-muted\">Price of 1 USDT</dt>\n            <dd className=\"font-bold\">{naira(Math.round(rate.rate))}</dd>\n            <dd className=\"text-xs text-muted\">{rate.source === \"roqqu\" ? \"Live rate from Roqqu\" : live ? \"Roqqu rate unavailable, using the set rate\" : \"Fixed sandbox rate\"}</dd>\n          </div>\n          <div>\n            <dt className=\"text-muted\">Roqqu withdrawal fee</dt>\n            <dd className=\"font-bold\">{fee?.percentage != null ? `${fee.percentage}%` : fee?.fee != null ? `${fee.fee} USDT` : \"Shown once live\"}</dd>\n            <dd className=\"text-xs text-muted\">Charged by Roqqu when the transfer is sent</dd>\n          </div>\n          <div>\n            <dt className=\"text-muted\">Roqqu account</dt>\n            <dd className=\"flex items-center gap-1 font-bold\"><ShieldCheck className=\"h-4 w-4 text-forest\" aria-hidden />{user.roqquStatus ? statusText[user.roqquStatus] ?? \"Checked\" : \"Not checked\"}</dd>\n            <dd>\n              <form action={checkMyRoqquStatus}>\n                <button className=\"mt-1 inline-flex items-center gap-1 text-xs font-semibold text-forest underline\"><RefreshCw className=\"h-3 w-3\" aria-hidden /> Check now</button>\n              </form>\n            </dd>\n          </div>\n        </dl>\n        <p className=\"mt-3 text-sm text-muted\">\n          To withdraw to your own wallet, use the withdraw form on your <Link href=\"/dashboard\" className=\"font-semibold text-forest underline\">dashboard</Link>.\n        </p>\n      </section>\n\n      {withdrawals.length > 0 && (\n        <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n          <h2 className=\"text-lg font-bold\">Withdrawals</h2>\n          <ul className=\"mt-3 divide-y divide-ink/10\">\n            {withdrawals.map((w) => {\n              const [label, tone] = W_STATUS[w.status] ?? [w.status, \"bg-cream text-muted\"];\n              const url = explorerUrl(w.network, w.txHash);\n              const old = Date.now() - w.createdAt.getTime() > 60 * 60 * 1000;\n              return (\n                <li key={w.id} className=\"space-y-2 py-3 text-sm\">\n                  <div className=\"flex items-center justify-between gap-3\">\n                    <span className=\"font-semibold\">{naira(w.amountNgn)} · {w.asset} on {w.network}</span>\n                    <span className={`rounded-full px-3 py-1 text-xs font-bold ${tone}`}>{label}</span>\n                  </div>\n                  {w.txHash && (\n                    <p className=\"break-all text-xs text-muted\">\n                      {w.txHash.startsWith(\"mock_\") ? \"Sandbox transfer (no blockchain record)\" : w.txHash}\n                      {url && (\n                        <a href={url} target=\"_blank\" rel=\"noopener noreferrer\" className=\"ml-2 inline-flex items-center gap-1 font-semibold text-forest underline\">\n                          View <ExternalLink className=\"h-3 w-3\" aria-hidden />\n                        </a>\n                      )}\n                    </p>\n                  )}\n                  {w.status === \"PROCESSING\" && w.refid && (\n                    <div className=\"flex flex-wrap gap-3\">\n                      <form action={checkWithdrawal.bind(null, w.reference)}>\n                        <button className=\"rounded-lg border border-ink/15 px-3 py-1.5 text-xs font-semibold hover:bg-cream\">Check status</button>\n                      </form>\n                      {old && (\n                        <form action={recoverWithdrawal.bind(null, w.reference)}>\n                          <button className=\"rounded-lg border border-ink/15 px-3 py-1.5 text-xs font-semibold hover:bg-cream\">Transfer stuck? Request refund</button>\n                        </form>\n                      )}\n                    </div>\n                  )}\n                </li>\n              );\n            })}\n          </ul>\n        </section>\n      )}\n\n      <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"text-lg font-bold\">Activity</h2>\n        {entries.length === 0 ? (\n          <p className=\"mt-2 text-sm text-muted\">Nothing yet. Add money to get started.</p>\n        ) : (\n          <ul className=\"mt-3 divide-y divide-ink/10\">\n            {entries.map((e) => {\n              const credit = e.amountNgn > 0;\n              const Icon = e.type === \"TASK_FUND\" ? Lock : credit ? ArrowDownLeft : ArrowUpRight;\n              return (\n                <li key={e.id} className=\"flex items-center justify-between gap-3 py-3 text-sm\">\n                  <span className=\"flex min-w-0 items-center gap-3\">\n                    <span className=\"flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-cream\">\n                      <Icon className=\"h-4 w-4 text-forest\" aria-hidden />\n                    </span>\n                    <span className=\"min-w-0\">\n                      <span className=\"block font-semibold\">{LABEL[e.type] ?? e.type}</span>\n                      <span className=\"block truncate text-xs text-muted\">\n                        {e.note ? e.note + \" · \" : \"\"}\n                        {e.createdAt.toLocaleDateString(\"en-NG\")}\n                      </span>\n                    </span>\n                  </span>\n                  <span className={`shrink-0 font-bold ${credit ? \"text-emerald-700\" : \"text-ink\"}`}>\n                    {credit ? \"+\" : \"-\"}{naira(Math.abs(e.amountNgn))}\n                  </span>\n                </li>\n              );\n            })}\n          </ul>\n        )}\n      </section>\n    </main>\n  );\n}\n","src/components/PaymentTrail.tsx":"import { Link2, ShieldCheck, ExternalLink, FlaskConical } from \"lucide-react\";\nimport { db } from \"@/lib/db\";\nimport { explorerUrl } from \"@/lib/proof\";\n\n// Shows how a job was paid: funded, held, released. If the funding came through Roqqu,\n// the transaction hash is shown with a link to the public blockchain record.\n// Public pages pass showAmounts={false}, because earnings are never shown on a Trust Passport.\nexport default async function PaymentTrail({\n  taskId,\n  credentialId,\n  showAmounts = false,\n}: {\n  taskId?: string;\n  credentialId?: string;\n  showAmounts?: boolean;\n}) {\n  let tid = taskId;\n  if (!tid && credentialId) tid = (await db.credential.findUnique({ where: { id: credentialId }, select: { taskId: true } }))?.taskId;\n  if (!tid) return null;\n  const [task, fund] = await Promise.all([\n    db.task.findUnique({ where: { id: tid }, select: { rewardNgn: true } }),\n    db.payment.findFirst({ where: { taskId: tid, type: \"FUND\" }, orderBy: { createdAt: \"asc\" } }),\n  ]);\n  if (!task || !fund) return null;\n\n  const hash = fund.txHash;\n  const tx = hash ? await db.roqquTx.findFirst({ where: { hash }, select: { live: true } }) : null;\n  const url = explorerUrl(fund.network, hash);\n  const naira = \"₦\" + task.rewardNgn.toLocaleString(\"en-NG\");\n\n  return (\n    <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n      <h2 className=\"flex items-center gap-2 text-lg font-bold\">\n        <Link2 className=\"h-5 w-5 text-forest\" aria-hidden /> Payment trail\n      </h2>\n      <ol className=\"mt-3 space-y-3 text-sm\">\n        <li className=\"flex gap-3\">\n          <ShieldCheck className=\"mt-0.5 h-4 w-4 shrink-0 text-forest\" aria-hidden />\n          <span>\n            <b>Funded before work started.</b> {showAmounts ? `${naira} was locked from the hirer's wallet. ` : \"The reward was locked from the hirer's wallet. \"}\n            The freelancer was paid the moment the work was approved.\n          </span>\n        </li>\n        {hash ? (\n          <li className=\"flex gap-3\">\n            <ShieldCheck className=\"mt-0.5 h-4 w-4 shrink-0 text-forest\" aria-hidden />\n            <span>\n              <b>{tx?.live === false ? \"Wallet top-up settled on Roqqu's test network.\" : \"Wallet top-up settled through Roqqu.\"}</b>{\" \"}\n              <span className=\"break-all font-mono text-xs\">{hash.length > 22 ? `${hash.slice(0, 10)}...${hash.slice(-8)}` : hash}</span>\n              {url && (\n                <a href={url} target=\"_blank\" rel=\"noopener noreferrer\" className=\"ml-2 inline-flex items-center gap-1 font-semibold text-forest underline\">\n                  View on the blockchain <ExternalLink className=\"h-3.5 w-3.5\" aria-hidden />\n                </a>\n              )}\n            </span>\n          </li>\n        ) : (\n          <li className=\"flex gap-3\">\n            <FlaskConical className=\"mt-0.5 h-4 w-4 shrink-0 text-muted\" aria-hidden />\n            <span className=\"text-muted\">This job was paid in demo mode, so there is no blockchain transaction to show.</span>\n          </li>\n        )}\n      </ol>\n    </section>\n  );\n}\n","scripts/simulate-roqqu-webhook.mjs":"// Sends a realistic, encrypted Roqqu webhook to your own site, so you can test everything\n// before Roqqu can reach you.\n//\n//   node scripts/simulate-roqqu-webhook.mjs payment_link_completed <reference>\n//   node scripts/simulate-roqqu-webhook.mjs payment_link_overpaid  <reference>\n//   node scripts/simulate-roqqu-webhook.mjs payment_link_failed    <reference>\n//   node scripts/simulate-roqqu-webhook.mjs token_received <address> <usdtAmount>\n//   node scripts/simulate-roqqu-webhook.mjs token_sent     <refid>\n//   node scripts/simulate-roqqu-webhook.mjs token_refunded <refid>\n//\n// Target: http://localhost:3000 by default, or set WEBHOOK_TARGET=https://your-site\nimport fs from \"node:fs\";\nimport crypto from \"node:crypto\";\n\nconst env = {};\ntry {\n  for (const line of fs.readFileSync(\".env\", \"utf8\").split(/\\r?\\n/)) {\n    const m = line.match(/^\\s*([A-Z0-9_]+)\\s*=\\s*\"?([^\"]*)\"?\\s*$/);\n    if (m) env[m[1]] = m[2];\n  }\n} catch {}\nconst key = (process.env.ROQQU_WEBHOOK_KEY || env.ROQQU_WEBHOOK_KEY || process.env.ROQQU_SECRET_KEY || env.ROQQU_SECRET_KEY || \"\").trim();\nif (key.length < 32) {\n  console.error(\"Your ROQQU_SECRET_KEY is missing or shorter than 32 characters. Roqqu uses its first 32 characters to encrypt webhooks.\");\n  process.exit(1);\n}\n\nconst [type, a, b] = process.argv.slice(2);\nconst hash = \"0x\" + crypto.randomBytes(32).toString(\"hex\");\nconst id = \"evt_sim_\" + crypto.randomBytes(6).toString(\"hex\");\nconst now = new Date().toISOString();\nconst customer = { email: \"test@trustloop.app\", first_name: \"Test\", last_name: \"User\" };\n\nfunction link(event_type, extra) {\n  return {\n    event_id: id, event_type, datetime: now,\n    meta_data: {\n      payment_link_refid: \"link_\" + id, payment_reference: a, amount_required: 1000, amount_currency: \"ngn\",\n      amount_received: \"0.67\", amount_received_usd: 1000, overpaid_amount: \"0\", overpaid_amount_usd: 0,\n      underpaid_amount: \"0\", underpaid_amount_usd: 0, token: \"USDT\", value: \"0.67\", hash, status: \"completed\",\n      customer, address: \"TSimulatedAddress\", network: \"trc20\", metadata: {}, ...extra,\n    },\n  };\n}\nconst events = {\n  payment_link_completed: () => link(\"payment_link_completed\", {}),\n  payment_link_overpaid: () => link(\"payment_link_completed_overpaid\", { overpaid_amount: \"0.1\", overpaid_amount_usd: 150 }),\n  payment_link_failed: () => link(\"payment_link_failed\", { status: \"failed\", underpaid_amount: \"0.2\", underpaid_amount_usd: 300 }),\n  token_received: () => ({ event_id: id, event_type: \"token_received\", datetime: now,\n    meta_data: { address: a, extra: null, network: \"trc20\", token: \"usdt\", value: b ?? \"5\", hash, status: \"confirmed\", customer } }),\n  token_sent: () => ({ event_id: id, event_type: \"token_sent\", datetime: now,\n    meta_data: { destination: \"TDest\", extra: null, network: \"trc20\", token: \"usdt\", value: \"5\", hash, reference: a, status: \"processed\" } }),\n  token_refunded: () => ({ event_id: id, event_type: \"token_refunded\", datetime: now,\n    meta_data: { network: \"trc20\", token: \"usdt\", value: \"5\", hash: \"admin_refund\", status: \"confirmed\", refid: a } }),\n};\nif (!events[type] || !a) {\n  console.error(\"Usage: node scripts/simulate-roqqu-webhook.mjs <\" + Object.keys(events).join(\"|\") + \"> <reference|address|refid> [amount]\");\n  process.exit(1);\n}\n\nconst iv = crypto.randomBytes(16);\nconst c = crypto.createCipheriv(\"aes-256-ctr\", Buffer.from(key.slice(0, 32), \"utf8\"), iv);\nconst cipher = Buffer.concat([c.update(Buffer.from(JSON.stringify(events[type]()), \"utf8\")), c.final()]).toString(\"hex\");\n\nconst target = (process.env.WEBHOOK_TARGET || \"http://localhost:3000\").replace(/\\/$/, \"\") + \"/api/roqqu/webhook\";\nconst res = await fetch(target, { method: \"POST\", headers: { \"content-type\": \"application/json\", \"x-api-key\": iv.toString(\"hex\") }, body: JSON.stringify({ hash: cipher }) });\nconsole.log(res.status, await res.text());\n"};
// TrustLoop: Roqqu deep integration installer. Safe to run twice.
const fs = require("fs");
const path = require("path");
const root = process.cwd();
if (!fs.existsSync(path.join(root, "prisma", "schema.prisma")) || !fs.existsSync(path.join(root, "src"))) {
  console.error("Run this from your trustloop project folder (the one that has prisma and src).");
  process.exit(1);
}
const backupDir = path.join(root, ".roqqu-backup");
const done = [], warn = [];

const readN = (p) => { const raw = fs.readFileSync(p, "utf8"); return { text: raw.replace(/\r\n/g, "\n"), crlf: raw.includes("\r\n") }; };
const writeN = (p, text, crlf) => fs.writeFileSync(p, crlf ? text.replace(/\n/g, "\r\n") : text);

// 1. Write files (backing up any that already exist).
for (const [rel, content] of Object.entries(FILES)) {
  const abs = path.join(root, rel);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  if (fs.existsSync(abs)) {
    const cur = fs.readFileSync(abs, "utf8").replace(/\r\n/g, "\n");
    if (cur === content) { continue; }
    const b = path.join(backupDir, rel);
    fs.mkdirSync(path.dirname(b), { recursive: true });
    if (!fs.existsSync(b)) fs.copyFileSync(abs, b);
  }
  fs.writeFileSync(abs, content);
  done.push("wrote " + rel);
}

// 2. Small edits to existing files. Each one checks that its anchor exists exactly once.
function patch(rel, label, edits, optional) {
  const abs = path.join(root, rel);
  if (!fs.existsSync(abs)) { if (!optional) warn.push(`${label}: ${rel} not found`); return false; }
  let { text, crlf } = readN(abs);
  const orig = text;
  for (const e of edits) {
    if (e.skipIf && text.includes(e.skipIf)) continue;
    const count = text.split(e.find).length - 1;
    if (count !== 1) { warn.push(`${label}: could not find the spot to edit in ${rel} (${e.what})`); return false; }
    text = text.replace(e.find, () => e.replace);
  }
  if (text !== orig) {
    const b = path.join(backupDir, rel);
    fs.mkdirSync(path.dirname(b), { recursive: true });
    if (!fs.existsSync(b)) fs.copyFileSync(abs, b);
    writeN(abs, text, crlf);
    done.push("edited " + rel);
  }
  return true;
}

// Prisma schema: add fields to existing models, and two new models.
(function schema() {
  const rel = "prisma/schema.prisma";
  const abs = path.join(root, rel);
  let { text, crlf } = readN(abs);
  const orig = text;
  const addFields = (model, fields) => {
    const re = new RegExp(`(model ${model} \\{[\\s\\S]*?)(\\n\\})`);
    const m = text.match(re);
    if (!m) { warn.push(`schema: model ${model} not found`); return; }
    const body = m[1];
    const missing = fields.filter((f) => !new RegExp(`^\\s*${f.split(/\s+/)[0]}\\s`, "m").test(body));
    if (!missing.length) return;
    text = text.replace(re, (_, a, b) => a + "\n" + missing.map((f) => "  " + f).join("\n") + b);
  };
  addFields("Deposit", ["txHash String?", "network String?", "token String?"]);
  addFields("Withdrawal", ["refid String?"]);
  addFields("User", ["roqquStatus String?", "roqquCheckedAt DateTime?", "addresses DepositAddress[]"]);
  if (!text.includes("model DepositAddress")) {
    text += `
model DepositAddress {
  id        String   @id @default(cuid())
  user      User     @relation(fields: [userId], references: [id])
  userId    String
  network   String
  address   String
  sandbox   Boolean  @default(false)
  createdAt DateTime @default(now())

  @@unique([userId, network])
  @@index([address])
}
`;
  }
  if (!text.includes("model RoqquTx")) {
    text += `
model RoqquTx {
  id        String   @id @default(cuid())
  kind      String
  live      Boolean  @default(false)
  userId    String?
  reference String?
  hash      String?
  token     String?
  network   String?
  value     Float?
  amountNgn Int?
  status    String
  note      String?
  createdAt DateTime @default(now())

  @@index([kind, createdAt])
  @@index([hash])
}
`;
  }
  if (text !== orig) {
    const b = path.join(backupDir, rel);
    fs.mkdirSync(path.dirname(b), { recursive: true });
    if (!fs.existsSync(b)) fs.copyFileSync(abs, b);
    writeN(abs, text, crlf);
    done.push("edited " + rel);
  }
})();

// Hirer funding record keeps the Roqqu hash of the latest top-up.
patch("src/app/actions/payments.ts", "payment trail", [
  { what: "import", skipIf: "latestRoqquHash", find: `import { payments } from "@/lib/payments";`, replace: `import { payments } from "@/lib/payments";\nimport { latestRoqquHash } from "@/lib/proof";` },
  { what: "funding record", skipIf: "...(await latestRoqquHash", find: `data: { taskId: task.id, type: "FUND", status: "CONFIRMED", reference, asset: "NGN", amount: String(task.rewardNgn) },`, replace: `data: { taskId: task.id, type: "FUND", status: "CONFIRMED", reference, asset: "NGN", amount: String(task.rewardNgn), ...(await latestRoqquHash(tx, userId)) },` },
]);

// Task page: show the payment trail once a job is paid.
patch("src/app/tasks/[id]/page.tsx", "task page", [
  { what: "import", skipIf: "PaymentTrail", find: `import TrustBadges from "@/components/TrustBadges";`, replace: `import TrustBadges from "@/components/TrustBadges";\nimport PaymentTrail from "@/components/PaymentTrail";` },
  { what: "render", skipIf: "<PaymentTrail", find: `{task.status === "PAID" && (`, replace: `{task.status === "PAID" && (isOwner || isAssigned) && <PaymentTrail taskId={task.id} showAmounts />}\n\n          {task.status === "PAID" && (` },
]);

// Trust Passport: badge when Roqqu has verified the account.
patch("src/app/p/[id]/page.tsx", "passport", [
  { what: "icon import", skipIf: "ShieldCheck", find: `import { BadgeCheck, UserPlus,`, replace: `import { ShieldCheck, BadgeCheck, UserPlus,` },
  { what: "badge", skipIf: "Verified on Roqqu", find: `Trust Passport · built from approved, signed work\n          </p>`, replace: `Trust Passport · built from approved, signed work\n          </p>\n          {person.roqquStatus === "verified" && (\n            <p className="mt-1 flex items-center gap-2 text-sm text-muted">\n              <ShieldCheck className="h-4 w-4 text-forest" aria-hidden /> Verified on Roqqu\n            </p>\n          )}` },
]);

// Public verify page: show the payment trail (no amounts). Only edited if it looks as expected.
(function verify() {
  const rel = "src/app/verify/[id]/page.tsx";
  const abs = path.join(root, rel);
  if (!fs.existsSync(abs)) { warn.push("verify page: not found at " + rel + ". Send me that file and I will add the payment trail to it."); return; }
  const { text } = readN(abs);
  if (text.includes("PaymentTrail")) return;
  const hasId = /const \{ id \} = await params;/.test(text);
  const closings = text.split("</Shell>").length - 1;
  if (!hasId || closings !== 1) { warn.push("verify page: has a different layout than expected. Send me that file and I will add the payment trail to it."); return; }
  const imp = text.match(/^import Shell from "@\/components\/Shell";$/m);
  if (!imp) { warn.push("verify page: could not find the Shell import. Send me that file."); return; }
  patch(rel, "verify page", [
    { what: "import", find: imp[0], replace: imp[0] + `\nimport PaymentTrail from "@/components/PaymentTrail";` },
    { what: "render", find: "</Shell>", replace: `<div className="mt-6"><PaymentTrail credentialId={id} /></div>\n    </Shell>` },
  ]);
})();

// Keep backups out of git.
try {
  const gi = path.join(root, ".gitignore");
  const cur = fs.existsSync(gi) ? fs.readFileSync(gi, "utf8") : "";
  if (!cur.includes(".roqqu-backup")) fs.appendFileSync(gi, (cur.endsWith("\n") || !cur ? "" : "\n") + ".roqqu-backup/\n");
} catch {}

console.log("\n" + done.map((d) => "  " + d).join("\n"));
if (warn.length) console.log("\nNeeds a look:\n" + warn.map((w) => "  - " + w).join("\n"));
console.log("\nInstalled. Next: npx prisma migrate dev --name roqqu_deep   then   npx prisma generate");
